function adapt(input, solve, kit) {
  const [specs] = input;
  const functions = specs.map((spec, index) => () => {
    kit.trace(`functions[${index}] is called`);
    const failing = spec.reject !== undefined;
    const outcome = failing ? spec.reject : spec.resolve;
    const settle = () => kit.trace(`The promise of functions[${index}] ${failing ? 'rejects' : 'resolves'} with ${JSON.stringify(outcome)}`);
    if (spec.t === 0) {
      settle();
      return failing ? Promise.reject(outcome) : Promise.resolve(outcome);
    }
    return new Promise((resolve, reject) => setTimeout(() => {
      settle();
      if (failing) reject(outcome);
      else resolve(outcome);
    }, spec.t));
  });
  // Each outcome object lists status first, then value or reason, so key order never decides a verdict.
  const tidy = (entry) => {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) return entry;
    const ordered = {};
    for (const key of ['status', 'value', 'reason', ...Object.keys(entry).sort()]) {
      if (Object.hasOwn(entry, key) && !Object.hasOwn(ordered, key)) ordered[key] = entry[key];
    }
    return ordered;
  };
  const start = Date.now();
  kit.trace(`promiseAllSettled is called with ${specs.length} function${specs.length === 1 ? '' : 's'}`);
  // The exercise asks for a solution without the built-in Promise.allSettled.
  const builtin = Promise.allSettled;
  Promise.allSettled = () => { throw new Error('Solve this without the built-in Promise.allSettled.'); };
  let promise;
  try { promise = solve(functions); } finally { Promise.allSettled = builtin; }
  if (!promise || typeof promise.then !== 'function') throw new Error('promiseAllSettled must return a promise.');
  return promise.then((values) => {
    if (!Array.isArray(values)) throw new Error('The returned promise must resolve with an array of outcome objects.');
    const tidied = values.map(tidy);
    kit.trace(`The returned promise resolves with ${JSON.stringify(tidied)}`);
    return { t: Date.now() - start, values: tidied };
  }, (reason) => {
    const rejected = reason instanceof Error ? String(reason) : reason;
    kit.trace(`The returned promise rejects with ${JSON.stringify(rejected)}`);
    return { t: Date.now() - start, rejected };
  });
}

