function promiseAllSettled(functions) {
  // Turn every promise into one that always resolves with its outcome, then wait for all of them together.
  const outcomes = functions.map((fn) => fn().then(
    (value) => ({ status: 'fulfilled', value }),
    (reason) => ({ status: 'rejected', reason }),
  ));
  return Promise.all(outcomes);
}

