function generate(rand, size) {
  const count = size === 'small' ? 1 + Math.floor(rand() * 4) : 6 + Math.floor(rand() * 5);
  const maxTime = size === 'small' ? 120 : 1000;
  const failRate = rand() * 0.7;
  const functions = [];
  for (let i = 0; i < count; i++) {
    const t = rand() < 0.1 ? 0 : Math.floor(rand() * (maxTime + 1));
    if (rand() < failRate) functions.push({ t, reject: `Error ${i}` });
    else functions.push({ t, resolve: Math.floor(rand() * (size === 'small' ? 21 : 2001)) - (size === 'small' ? 10 : 1000) });
  }
  return [functions];
}
